package com.pasm.medical.db;

import io.zonky.test.db.postgres.embedded.EmbeddedPostgres;
import org.flywaydb.core.Flyway;
import org.flywaydb.core.api.output.MigrateResult;
import org.junit.jupiter.api.Test;

import javax.sql.DataSource;
import java.sql.Connection;
import java.sql.ResultSet;
import java.sql.Statement;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * 迁移脚本的**真 PostgreSQL** 验证（嵌入式 PG，不依赖 Docker）。
 *
 * <p>为什么不能只靠 H2：实体里用了 {@code TIMESTAMP WITH TIME ZONE}、
 * {@code GENERATED BY DEFAULT AS IDENTITY}、索引与约束命名 —— 这些在 H2 上"大体能过"，
 * 但在目标库 PostgreSQL 上可能因为语法/权限/类型差异直接失败。生产跑的是 PG，
 * 所以迁移必须在 PG 上真的执行一遍。
 *
 * <p>本测试断言四件事：
 * <ol>
 *   <li>V1 能在真实 PG 上执行成功；</li>
 *   <li>5 张业务表 + 7 个关键索引真的建出来了；</li>
 *   <li>自增主键可用（INSERT 不传 id 能返回数字）；</li>
 *   <li>再跑一次是**幂等**的（不会重复执行 V1）。</li>
 * </ol>
 */
class FlywayPostgresTest {

    @Test
    void migrationCreatesUsableSchemaOnRealPostgres() throws Exception {
        try (EmbeddedPostgres pg = EmbeddedPostgres.builder().start()) {
            DataSource ds = pg.getPostgresDatabase();

            MigrateResult first = Flyway.configure()
                    .dataSource(ds)
                    .locations("classpath:db/migration")
                    .load()
                    .migrate();
            assertEquals(1, first.migrationsExecuted, "V1 应执行一次");

            try (Connection c = ds.getConnection(); Statement st = c.createStatement()) {
                assertEquals(5, count(st,
                        "SELECT count(*) FROM information_schema.tables "
                                + "WHERE table_schema='public' AND table_name IN "
                                + "('patients','encounters','ai_audit',"
                                + "'knowledge_docs','system_config')"),
                        "5 张业务表都应存在");

                assertEquals(7, count(st,
                        "SELECT count(*) FROM pg_indexes WHERE schemaname='public' "
                                + "AND indexname IN ('idx_audit_occurred_at',"
                                + "'idx_audit_action_time','idx_audit_patient_time',"
                                + "'idx_audit_action_refused',"
                                + "'idx_encounters_patient_time',"
                                + "'idx_encounters_department','idx_kb_department_status')"),
                        "7 个关键索引都应存在");

                assertEquals(1, count(st,
                        "SELECT count(*) FROM flyway_schema_history "
                                + "WHERE version='1' AND success=true"),
                        "flyway_schema_history 应记录 V1 success");

                st.execute("INSERT INTO patients(ref, created_at) "
                        + "VALUES ('flyway-test-p1', now())");
                try (ResultSet rs = st.executeQuery(
                        "INSERT INTO encounters(patient_ref, occurred_at) "
                                + "VALUES ('flyway-test-p1', now()) RETURNING id")) {
                    assertTrue(rs.next(), "RETURNING 应返回一行");
                    assertTrue(rs.getLong(1) > 0, "自增主键应生成正整数");
                }
                st.execute("DELETE FROM encounters WHERE patient_ref='flyway-test-p1'");
                st.execute("DELETE FROM patients WHERE ref='flyway-test-p1'");
            }

            MigrateResult second = Flyway.configure()
                    .dataSource(ds)
                    .locations("classpath:db/migration")
                    .load()
                    .migrate();
            assertEquals(0, second.migrationsExecuted, "二次迁移应幂等：不重复执行 V1");
        }
    }

    private static int count(Statement st, String sql) throws Exception {
        try (ResultSet rs = st.executeQuery(sql)) {
            assertTrue(rs.next(), "计数查询应有结果");
            return rs.getInt(1);
        }
    }
}
